def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    r = (me.x * me.x + me.y * me.y) ** 0.5
    d = distance_to(enemy.x, enemy.y)
    if r > 5.2 and d > 2.0:
        b = bearing_to(0.0, 0.0)
    else:
        b = bearing_to(enemy.x, enemy.y)
    if b > 20:
        return (0.3, 1.0)
    if b < -20:
        return (1.0, 0.3)
    return (1.0, 1.0)


