            out.append(spin("front", 3500))
    return out

def limit_value(x):
    return max(-1.0, min(1.0, x))


def drive(me, enemy, arena):
    if not me.can_drive:
        return None

    front = me.weapons.get("front", {})
    if front.get("type") == "lifter" and front.get("engaged", False):
        return (0.0, 0.0)

    dist = distance_to(enemy.x, enemy.y)
    bearing = bearing_to(enemy.x, enemy.y)

    if abs(bearing) > 105.0:
        side = 1.0 if bearing > 0.0 else -1.0
        return (-0.85 * side, 0.85 * side)

    if dist < 2.65:
        if abs(bearing) > 48.0:
            side = 1.0 if bearing > 0.0 else -1.0
            return (-0.70 * side, 0.70 * side)
        return (0.70, 0.70)

    if abs(bearing) > 35.0:
        side = 1.0 if bearing > 0.0 else -1.0
        return (0.50 - 0.40 * side, 0.50 + 0.40 * side)

    return (1.0, 1.0)


def weapons(me, enemy, arena):
    commands = []
    front = me.weapons.get("front", {})
    rear = me.weapons.get("back", {})

    if me.inverted and not me.airborne and not me.righting:
        flipper_ready = (
            rear.get("type") == "flipper"
            and rear.get("health", 0.0) > 0.0
            and rear.get("ready", False)
            and rear.get("shots_left", 0) > 0
        )
        lifter_alive = (
            front.get("type") == "lifter"
            and front.get("health", 0.0) > 0.0
        )
        if flipper_ready or lifter_alive:
            commands.append(self_right())
            return commands

    dist = distance_to(enemy.x, enemy.y)
    bearing = bearing_to(enemy.x, enemy.y)

    own_ready = (
        not me.airborne
        and not me.held
        and not me.lifted
        and not me.inverted
        and not me.on_side
    )
    enemy_ready = (
        not enemy.airborne
        and not enemy.inverted
        and not enemy.on_side
    )

    if front.get("type") == "lifter":
        state = front.get("state", "down")
        cooldown = front.get("cooldown", 0.0)
        start_time = me.memory.get("lift_start", -100.0)
        cleared = me.memory.get("lift_cleared", False)

        if state == "down":
            if cooldown > 0.0:
                if not cleared:
                    commands.append(lower("front"))
                    me.memory["lift_cleared"] = True
            elif (
                own_ready
                and enemy_ready
                and dist < 2.65
                and abs(bearing) < 65.0
            ):
                commands.append(lift("front"))
                me.memory["lift_start"] = arena.time
                me.memory["lift_cleared"] = False

        elif state == "up":
            if front.get("engaged", False):
                me.memory["lift_start"] = -100.0
            else:
                elapsed = arena.time - start_time
                if cooldown > 0.0 or elapsed > 1.0:
                    commands.append(lower("front"))
                    me.memory["lift_start"] = -100.0
                    me.memory["lift_cleared"] = True

    if (
        rear.get("type") == "flipper"
        and own_ready
        and enemy_ready
        and rear.get("health", 0.0) > 0.0
        and rear.get("ready", False)
        and rear.get("shots_left", 0) > 0
        and dist < 1.8
        and abs(bearing) > 125.0
    ):
        commands.append(flip("back"))

    return commands

